/// <summary>
/// Controller for the @SYS313987 report.
/// Extends <c>SrsReportRunController</c> to provide menu item integration
/// and pre-prompt contract initialization.
/// </summary>
public class ConDemoCreditLimitReportController extends SrsReportRunController
{
}

Method.Source:
/// <summary>
/// Entry point for the report. Creates the controller and starts execution.
/// </summary>
/// <param name="_args">The <c>Args</c> object from the menu item caller.</param>
public static void main(Args _args)
{
    ConDemoCreditLimitReportController controller = new ConDemoCreditLimitReportController();
    controller.parmReportName(ssrsReportStr(ConDemoCreditLimitReport, Report));
    controller.parmArgs(_args);
    controller.startOperation();
}

